// Decides whether the digest must be sent in this run.
// The manual path always continues. The scheduled path continues only when the
// current hour and weekday in America/Bogota match send_hour and send_days.
const config = {};
for (const row of $('Config').all()) {
  const key = String(row.json.key ?? '').trim();
  if (key) config[key] = String(row.json.value ?? '').trim();
}

const manual = $('Manual Trigger').isExecuted;

const parts = new Intl.DateTimeFormat('en-US', {
  timeZone: 'America/Bogota',
  weekday: 'short',
  hour: 'numeric',
  hourCycle: 'h23',
}).formatToParts(new Date());
const hour = Number(parts.find((p) => p.type === 'hour').value);
const weekday = parts.find((p) => p.type === 'weekday').value.toLowerCase();

const sendHour = Number(config.send_hour);
const sendDays = (config.send_days ?? '')
  .toLowerCase()
  .split(',')
  .map((d) => d.trim())
  .filter(Boolean);

const hourOk = config.send_hour !== undefined && config.send_hour !== '' && sendHour === hour;
const dayOk = sendDays.includes('all') || sendDays.includes(weekday);

if (!manual && !(hourOk && dayOk)) {
  return [];
}

return [{ json: { config, manual, hour, weekday } }];

// Builds, for each active user, the list of feeds that match their topics and
// scope, and the list of distinct feed URLs to fetch once per run.
const norm = (v) => String(v ?? '').trim();
const lower = (v) => norm(v).toLowerCase();
const isTrue = (v) => norm(v).toUpperCase() === 'TRUE';

const feeds = $('Feeds')
  .all()
  .map((i) => i.json)
  .filter((f) => norm(f.url) && isTrue(f.active))
  .map((f) => ({
    name: norm(f.name),
    url: norm(f.url),
    topic: lower(f.topic),
    scope: lower(f.scope),
    language: lower(f.language),
  }));

const topicsByUser = {};
for (const { json: t } of $('Topics').all()) {
  const email = lower(t.user_email);
  const topic = lower(t.topic);
  if (!email || !topic) continue;
  topicsByUser[email] ??= [];
  if (!topicsByUser[email].includes(topic)) topicsByUser[email].push(topic);
}

const users = $('Users')
  .all()
  .map((i) => i.json)
  .filter((u) => norm(u.email) && isTrue(u.active))
  .map((u) => {
    const email = norm(u.email);
    const topics = topicsByUser[email.toLowerCase()] ?? [];
    const scope = lower(u.scope);
    const count = Math.trunc(Number(u.news_count));
    return {
      email,
      name: norm(u.name),
      language: lower(u.language) === 'es' ? 'es' : 'en',
      level: norm(u.level).toUpperCase(),
      scope,
      newsCount: Math.min(15, Math.max(1, Number.isFinite(count) ? count : 1)),
      topics,
      feeds: feeds.filter(
        (f) => topics.includes(f.topic) && (scope === 'both' || f.scope === scope),
      ),
    };
  });

const feedUrls = [...new Set(users.flatMap((u) => u.feeds.map((f) => f.url)))];

return [{ json: { users, feedUrls } }];
